repo.pkg/retention.py:
"""Retention sweep (used by pkg.cli)."""
import os


def expired(entries, keep_days):
    """Entries older than keep_days."""
    return [e for e in entries if e["age_days"] > keep_days]


def purge(directory, ages, keep_days):
    """Delete files older than keep_days; keep_days must be at least 1."""
    if keep_days < 1:
        raise ValueError("keep_days must be >= 1 (refusing to purge everything)")
    for name, age in ages.items():
        if age > keep_days:
            os.remove(os.path.join(directory, name))

